import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BeanPropertyMap._rename method.
 * Since _rename is protected, we use a subclass or access it via a test wrapper.
 */
public class BeanPropertyMap__rename_TriageGen0Test {

    // Subclass to expose the protected method for testing
    private static class BeanPropertyMapTestWrapper extends BeanPropertyMap {
        protected BeanPropertyMapTestWrapper(boolean caseInsensitive, java.util.Collection<SettableBeanProperty> props) {
            super(caseInsensitive, props);
        }

        @Override
        public SettableBeanProperty _rename(SettableBeanProperty prop, NameTransformer xf) {
            return super._rename(prop, xf);
        }
    }

    public interface NameTransformer {
        String transform(String name);
    }

    @Test
    public void testRename_NullProp() {
        BeanPropertyMapTestWrapper map = new BeanPropertyMapTestWrapper(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty result = map._rename(null, xf);

        assertNull(result);
    }

    @Test
    public void testRename_WithNewNameAndNewDeserializer() {
        BeanPropertyMapTestWrapper map = new BeanPropertyMapTestWrapper(false, Collections.emptyList());

        String oldName = "oldName";
        String newName = "newName";

        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);
        NameTransformer xf = mock(NameTransformer.class);
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        JsonDeserializer<?> unwrappedDeser = mock(JsonDeserializer.class);
        SettableBeanProperty renamedPropName = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedPropDeser = mock(SettableBeanProperty.class);

        // Setup behavior
        when(xf.transform(oldName)).thenReturn(newName);
        when(mockProp.getName()).thenReturn(oldName);
        when(mockProp.withSimpleName(newName)).thenReturn(renamedPropName);
        when(renamedPropName.getValueDeserializer()).thenReturn(mockDeser);
        when(mockDeser.unwrappingDeserializer(xf)).thenReturn(unwrappedDeser);

        // Ensure the deserializer is different to trigger the if (newDeser != deser) branch
        when(renamedPropName.withValueDeserializer(unwrappedDeser)).thenReturn(renamedPropDeser);

        SettableBeanProperty result = map._rename(mockProp, xf);

        assertEquals(renamedPropDeser, result);
    }

    @Test
    public void testRename_WithNewNameButSameDeserializer() {
        BeanPropertyMapTestWrapper map = new BeanPropertyMapTestWrapper(false, Collections.emptyList());

        String oldName = "oldName";
        String newName = "newName";

        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);
        NameTransformer xf = mock(NameTransformer.class);
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        SettableBeanProperty renamedPropName = mock(SettableBeanProperty.class);

        // Setup behavior
        when(xf.transform(oldName)).thenReturn(newName);
        when(mockProp.getName()).thenReturn(oldName);
        when(mockProp.withSimpleName(newName)).thenReturn(renamedPropName);
        when(renamedPropName.getValueDeserializer()).thenReturn(mockDeser);
        // Return the same deserializer to skip the withValueDeserializer call
        when(mockDeser.unwrappingDeserializer(xf)).thenReturn(mockDeser);

        SettableBeanProperty result = map._rename(mockProp, xf);

        assertEquals(renamedPropName, result);
    }

    @Test
    public void testRename_WithNewNameButNoDeserializer() {
        BeanPropertyMapTestWrapper map = new BeanPropertyMapTestWrapper(false, Collections.emptyList());

        String oldName = "oldName";
        String newName = "newName";

        SettableBeanProperty mockProp = mock(SettableBeanProperty.class);
        NameTransformer xf = mock(NameTransformer.class);
        SettableBeanProperty renamedPropName = mock(SettableBeanProperty.class);

        // Setup behavior
        when(xf.transform(oldName)).thenReturn(newName);
        when(mockProp.getName()).thenReturn(oldName);
        when(mockProp.withSimpleName(newName)).thenReturn(renamedPropName);
        when(renamedPropName.getValueDeserializer()).thenReturn(null);

        SettableBeanProperty result = map._rename(mockProp, xf);

        assertEquals(renamedPropName, result);
    }
}
